import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第四卷 退潮 · 第73章 开学","description":"","frontmatter":{},"headers":[],"relativePath":"第73章_开学.md","filePath":"第73章_开学.md"}'),r={name:"第73章_开学.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第四卷-退潮-·-第73章-开学" tabindex="-1">第四卷 退潮 · 第73章 开学 <a class="header-anchor" href="#第四卷-退潮-·-第73章-开学" aria-label="Permalink to &quot;第四卷 退潮 · 第73章 开学&quot;">​</a></h1><p>高三的秋，是从雾里开始的。</p><p>清早出门，巷子还泡在雾里。南雾县的江风漫进来，带着潮湿的凉，贴在脸上，软软的。我背着空书包往学校走，石板路滑滑的，鞋底蹭着青苔，发出细碎的轻响。路边桂花开了，香气很淡，被雾一泡，更淡了，只剩一点甜留在鼻尖。</p><p>宋阿婆坐在巷口，面前摆着小竹篮，里面是包好的海盐糖。她看到我，招手让我过去，抓了两颗塞进我手心。她的手很暖，指腹粗糙，带着甜香。</p><p>“开学了，带两颗，累了就吃。”她笑着说，眼角纹路挤在一起，“跟那个姑娘一人一颗，别独吞。”</p><p>我把糖攥紧，包装纸硌着掌心，心里发烫，点点头，跑进雾里。雾扑在脸上，凉凉的，睫毛上很快沾了水汽。</p><p>到校门口时，雾还没散。铁门上沾着水珠，摸一把，指尖全湿。老周站在雾里喊人，袖子挽到手肘，嗓门洪亮。</p><p>“都过来领纸条，先搬旧教室的东西，全部搬到朝南的新教室去。”</p><p>人群围上去，又散开。陈默挤到我身边，头发上全是雾水，亮晶晶的，手里抱着空纸箱。</p><p>“沈聿，咱俩一组，我就认你力气大。”他把箱子往我怀里塞了一半。</p><p>“你就是懒。”我说着接过来，指尖碰到纸板的潮气，凉凉的。</p><p>我们跟着人流往旧教室走。楼道里挤满了人，脚步声叠着箱子拖地的声音，热气混着灰尘的味道，闷闷的。旧教室门开着，桌椅歪着，黑板上还有没擦净的字迹，粉笔灰落在讲台上，白白的一层。</p><p>我弯腰装书，纸张味道扑上来，带着旧油墨的气息。书很沉，抱在怀里，书角硌着胸口，手臂很快发酸。林小满抱着一摞书进来，脸颊红红的，额头有汗。</p><p>“你的命你自己抱，别指挥我。”她推了陈默一把，惹得大家都笑。</p><p>顾远拎着两把椅子进来，走得很稳，气息都不乱。他看我一眼，声音沉沉的。</p><p>“走，一起抬桌子，一趟省一趟。”</p><p>我们抬起一张桌子，木头桌面凉凉的，边缘粗糙，蹭着掌心。往新教室走的路上，雾被拨开，阳光透进来，落在扶手上，水珠亮闪闪的。转角风很大，吹在出汗的后背上，凉得一抖。</p><p>新教室朝南，窗户很大，光涌进来，浮尘在光里打转。空气里有新刷墙的淡香，混着木头味，还有窗外飘来的桂花香。我把箱子放下，后背出了一层薄汗，衣服贴在身上，凉凉的。</p><p>老周把后墙那张座位表递给我和陈默，说贴正一点，别歪了等下又要重贴。陈默踩在椅子上举着纸角，我站在下面托着，纸很薄，边角一沾手就卷。我们先对齐墙上的铅笔印，再一点点往上推，陈默说往左一点，我说再往上抬一点，手指压着纸面慢慢抹平，胶带的黏味飘出来，有点酸，混着新墙的灰味。贴好后我退开两步看，纸边翘起一角，我又踮脚压回去，指腹蹭过纸面，涩涩的，像摸在旧书页上。陈默从椅子上跳下来，拍拍手说总算正了，老周在旁边点头说可以，以后就按这个坐。光落在表上，名字一行行印着，墨痕还带着热度。那一下我忽然想起刚进校那年也是这样贴表，那时我只敢偷偷找她的名字，如今她就在两排之外，手边就是我的水杯。</p><p>何晓抱着小盆栽进来，叶子绿得发亮，沾着水珠。她站在窗台前，小声问。</p><p>“这个放这里可以吗，我养了整个夏天，怕它换地方不习惯。”</p><p>林小满招手，声音脆脆的。</p><p>“放中间，光最好，你天天浇水，它肯定喜欢。”</p><p>何晓把盆栽放好，用手指轻轻碰了碰叶子，动作很轻。</p><p>老周走进来，拍拍手，教室安静下来。</p><p>“按纸条找座位，坐下就擦桌椅，马上发新书。”</p><p>我展开纸条，抬头去找。目光越过一张张桌椅，落在靠窗往后的那张桌子上。桌面有浅浅刻痕，摸上去糙糙的。而江苒，就坐在离我两排远的地方。</p><p>她正把书一本本拿出来，动作不快，头发松松挽着，有几缕落在颈边。她回头看了我一眼，眼睛弯了弯，又很快转回去，耳尖却红了。</p><p>隔着两排，我能看清她后脑的发旋，能看到她校服后领上沾的一点白灰，能听到她翻书时纸张的轻响。风从窗外进来，吹动她的发丝，也吹动她桌上书页，哗哗响。这个距离，近到能听见，远到碰不到，心里像被轻轻勾着。</p><p>陈默凑过来，压低声音笑。</p><p>“两排，这距离好，抬头就能看见。”</p><p>“去擦你的桌子。”我推他一把，耳朵发烫。</p><p>我拿起抹布去洗。水池边挤满人，水凉刺骨，溅到手腕上，激得一缩。回去擦桌子，灰尘卷起来，呛得鼻子痒，打了个喷嚏，眼泪都出来了。</p><p>“慢点擦，没人跟你抢。”江苒声音从两排外传来，带着笑，很轻。</p><p>我抬头，她也拿着抹布，手腕沾着水珠，亮亮的。</p><p>“你椅子还晃吗。”我问。</p><p>“有点，像荡船。”她晃了晃椅子，发出闷响，自己也笑了。</p><p>“待会儿帮你垫一下。”我说。</p><p>“好，等着。”她点头，眼睛亮亮的。</p><p>下课铃一响我就蹲到她椅子边，手里捏着一小块叠好的硬纸。先把椅子往前挪开，椅脚底粘着一点灰，我吹了吹，灰扑到指尖，有点凉。把纸片对折再对折，塞进短的那只椅脚下，用掌心压了压，再晃一晃，闷响轻了许多。江苒扶着桌沿看我，轻声说好了不晃了。我站起来拍掉手上的灰，掌心有点麻，鼻尖还沾着纸屑的味。她笑说谢谢，声音落在我耳边，像糖纸轻轻响了一下。</p><p>发新书时最热闹。书一摞摞抱进来，油墨香浓浓的，纸面崭新，摸上去滑滑的。大家传书，喊名字，笑声不断。我抱着自己的那份，沉沉的，压得胸口发闷，心里却踏实。</p><p>我把书码好，书脊对齐。想起宋阿婆的糖，我掏出来，两颗，包装纸有点皱，还带着余温。我起身走过两排，来到江苒桌边，心跳得很响。</p><p>“给，一人一颗，说好的。”我把糖放在她桌角。</p><p>她拿起糖，在手心转了转。</p><p>“宋阿婆给的吗，还是咸咸甜甜的味道。”</p><p>“嗯，她说开学要甜一下。”我说。</p><p>她把糖放进笔袋最前面的格子，很郑重，又拿出一张卡片递给我。卡片淡蓝色，像退潮后的海，上面画着小小浪花，边角有点毛，带着她手心的暖。</p><p>“这个给你，新教室新开始，夹在最难的书里，翻到就轻松一下。”她说，指尖碰到我掌心，凉凉的，一触就分开。</p><p>我捏着卡片回到座位，把它夹进书里。淡蓝一角露出来，在暗色书脊里很显眼。我剥开另一颗糖放进嘴里，咸味先散开，接着是甜，贴在舌尖，心里紧绷像是被泡软了。</p><p>窗外雾散了，阳光落在江苒背上，落在绿植叶子上，亮得晃眼。高三的秋，就这样落下来了，沉沉的，又甜甜的。</p><p>陈默用笔帽敲我桌子，挤眉弄眼。</p><p>“笑成这样，糖很甜吗。”</p><p>“垫椅子去。”我说着把糖纸展平，夹进书里。风把书页吹开一线，露出那抹淡蓝，像海在纸里轻轻晃。</p>',53)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
